// Read-only verification: Base44 may serve a summary fallback to crawlers
// instead of the record-specific metadata generated by RallyHub.
const site = 'https://rallyhub.ie';
const cases = [
  { path:'/', expected:'RallyHub | Your Next Game Starts Here' },
  { path:'/pickleball-clubs/clare', expected:/Clare/i },
  { path:'/directory/achill-pickleball', expected:/Achill/i },
  { path:'/directory/abc-pickleball-club', expected:/ABC Pickleball/i },
  { path:'/pickleball-venues/abc-pickleball-club/1-lake-rd', expected:/Lake Rd|ABC Pickleball|Pickleball at/i },
];
let failure = 0;
for (const {path,expected} of cases) {
  const response = await fetch(site+path,{headers:{'User-Agent':'Googlebot/2.1'},signal:AbortSignal.timeout(15000)});
  const html = await response.text();
  const title = (html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1]||'').replace(/&amp;/g,'&').trim();
  const snapshot = /id=["']seo-snapshot["']/.test(html);
  const pass = response.ok && (typeof expected==='string'?title===expected:expected.test(title)) && !snapshot;
  if (!pass) failure++;
  console.log(JSON.stringify({path,status:response.status,title,snapshot,pass}));
}
console.log(`LIVE_DIRECTORY_SEO ${cases.length-failure}/${cases.length}`);
if(failure) process.exitCode=1;
